import pyomo.environ as pyo

DATA = {
    "N": 4,
    "cost": {
        (1, 2): 61, (1, 3): 17, (1, 4): 81,
        (2, 1): 61, (2, 3): 40, (2, 4): 52,
        (3, 1): 17, (3, 2): 40, (3, 4): 23,
        (4, 1): 81, (4, 2): 52, (4, 3): 23,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    N = d["N"]

    model = pyo.ConcreteModel()

    model.N = pyo.RangeSet(1, N)
    model.A = pyo.Set(
        initialize=[(i, j) for i in range(1, N + 1) for j in range(1, N + 1) if i != j],
        dimen=2,
    )

    model.x = pyo.Var(model.A, within=pyo.Binary)
    model.u = pyo.Var(model.N, within=pyo.NonNegativeReals, bounds=(1, N))

    def obj_rule(m):
        return sum(d["cost"][(i, j)] * m.x[i, j] for (i, j) in m.A)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Each city departed exactly once
    def out_rule(m, i):
        return sum(m.x[i, j] for j in m.N if (i, j) in m.A) == 1
    model.out_deg = pyo.Constraint(model.N, rule=out_rule)

    # Each city entered exactly once
    def in_rule(m, j):
        return sum(m.x[i, j] for i in m.N if (i, j) in m.A) == 1
    model.in_deg = pyo.Constraint(model.N, rule=in_rule)

    # Pin order of city 1 (start city arbitrary; fixes cycle reference)
    model.fix_start = pyo.Constraint(expr=model.u[1] == 1)

    # Subtour elimination (MTZ): u[j] >= u[i] + 1 - N*(1 - x[i,j])
    def mtz_rule(m, i, j):
        return m.u[j] >= m.u[i] + 1 - N * (1 - m.x[i, j])
    model.mtz = pyo.Constraint(model.A, rule=mtz_rule)

    return model
